-- =============================================================================
-- Location-based serviceability for the website direct booking flow
-- (2026-09-17)
--
-- Stores the instructor driving-zone POLYGONS from the Google My Maps export
-- ("Copy of Lane instructor driving zones", public, mid=1u2uFoJZVxhlVyv3WcTv5nA7Z-uITbYw)
-- plus the KML placemark name -> DB instructor aliases, so geometry is
-- DB-driven (admin-editable, re-ingest safe, no code hardcoding, no redeploy).
--
-- geometry JSONB format: array of rings; each ring is an array of [lng, lat]
-- pairs; ring 0 is the outer boundary, any further rings are holes. A point is
-- inside the zone when it is inside the outer ring and outside every hole.
--
-- Serviceability rule (backend-authoritative): a learner's lat/lng is
-- serviceable when EITHER it falls in an instructor's zone polygon OR within
-- that instructor's base radius (Instructor.radius around latitude/longitude).
-- The derived service area then comes from that instructor's
-- Instructor.areas[] joining active Serviceable_Areas.
--
-- Two KML polygons have NO DB instructor match and are intentionally NOT
-- seeded (documented follow-ups from the 2026-09-12 ambiguity report):
--   * "Santhosh"                (polygon centroid near BTM, own point 13.65 km away)
--   * "Prabhavathy Sudesh Kumar"
-- These need a DB decision (create the instructor rows) before they can serve.
-- Instructor "Ameen / Arokia" has TWO zones (source names "Ameen / Arokia" +
-- "Syed Ahmed ameen") and is seeded twice, which is intended.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. zone_name_aliases — KML placemark name -> canonical Instructor.name. Used
--    at seed/ingest time to resolve a polygon to its instructor.
-- -----------------------------------------------------------------------------
create table if not exists public.zone_name_aliases (
  source_name text primary key,
  instructor_name text not null,
  created_at timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- 2. instructor_service_zones — an instructor's driving zone polygon.
-- -----------------------------------------------------------------------------
create table if not exists public.instructor_service_zones (
  id uuid primary key default gen_random_uuid(),
  instructor_id uuid not null references public."Instructor"(id_instructor) on delete cascade,
  source_name text not null unique,
  geometry jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_instructor_service_zones_instructor
  on public.instructor_service_zones (instructor_id);

-- -----------------------------------------------------------------------------
-- 3. Row level security — service-role only (no policies => anon/authenticated
--    denied by default), matching the other direct-booking tables.
-- -----------------------------------------------------------------------------
alter table public.zone_name_aliases enable row level security;
alter table public.instructor_service_zones enable row level security;

